#include <utility>
#include <string>

void g(std::pair<const int, std::string> p) { /* ... */ }

int main() {
    std::pair<int, const char*> p(42, "hello");

    // 1. Calls default copy constructor (types match exactly)
    std::pair<int, const char*> p_copy = p;

    // 2. Calls template converting constructor (int -> const int, const char* -> std::string)
    g(p); 

    return 0;
}
